The strongest paradigm to solve longhorizon reasoning and characterexact state retention without falling back on conventional linear conversation logs is an explicit Markovian Execution State Engine (formalized in  / ). Instead of accumulating appendonly prompt transcripts where historical noise compounds, the execution decomposes into formal state transitions:[1][2]

\[
A_{t} = (P, \, \Sigma_{t}, \, O_{t})
\]

The runtime maintains an explicit state dictionary \(\Sigma_t\) alongside the immutable specification \(P\) and the current observation \(O_t\). Every transition strictly updates the canonical state \(\Sigma_{t+1} \leftarrow \Sigma_t \oplus \Delta\Sigma\) and permanently drops transient reasoning traces.[3][1]

 Implementation

zig
const std = @import("std");

pub const StateValueType = enum {
    string,
    integer,
    boolean,
    null_value,
};

pub const StateValue = struct {
    tag: StateValueType,
    data: union {
        str: []const u8,
        int: i64,
        boolean: bool,
        none: void,
    },
};

pub const StateMap = std.StringHashMap(StateValue);

pub const ExecutionStateEngine = struct {
    allocator: std.mem.Allocator,
    state: StateMap,
    step_count: usize,

    pub fn init(allocator: std.mem.Allocator) ExecutionStateEngine {
        return .{
            .allocator = allocator,
            .state = StateMap.init(allocator),
            .step_count = 0,
        };
    }

    pub fn deinit(self: *ExecutionStateEngine) void {
        var iter = self.state.iterator();
        while (iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            if (entry.value_ptr.tag == .string) {
                self.allocator.free(entry.value_ptr.data.str);
            }
        }
        self.state.deinit();
    }

    pub fn applyPatch(self: *ExecutionStateEngine, key: []const u8, value: StateValue) !void {
        if (value.tag == .null_value) {
            if (self.state.fetchRemove(key)) |kv| {
                self.allocator.free(kv.key);
                if (kv.value.tag == .string) {
                    self.allocator.free(kv.value.data.str);
                }
            }
            return;
        }

        const gop = try self.state.getOrPut(key);
        if (gop.found_existing) {
            if (gop.value_ptr.tag == .string) {
                self.allocator.free(gop.value_ptr.data.str);
            }
        } else {
            gop.key_ptr.* = try self.allocator.dupe(u8, key);
        }

        if (value.tag == .string) {
            gop.value_ptr.* = StateValue{
                .tag = .string,
                .data = .{ .str = try self.allocator.dupe(u8, value.data.str) },
            };
        } else {
            gop.value_ptr.* = value;
        }
    }

    pub fn step(self: *ExecutionStateEngine, patch_keys: []const []const u8, patch_vals: []const StateValue) !void {
        std.debug.assert(patch_keys.len == patch_vals.len);
        for (patch_keys, 0..) |key, idx| {
            try self.applyPatch(key, patch_vals[idx]);
        }
        self.step_count += 1;
    }

    pub fn get(self: *const ExecutionStateEngine, key: []const u8) ?StateValue {
        return self.state.get(key);
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var engine = ExecutionStateEngine.init(allocator);
    defer engine.deinit();

    const k1 = "active_goal";
    const v1 = StateValue{ .tag = .string, .data = .{ .str = "execute_plan_alpha" } };
    try engine.applyPatch(k1, v1);

    const k2 = "retry_count";
    const v2 = StateValue{ .tag = .integer, .data = .{ .int = 0 } };
    try engine.applyPatch(k2, v2);

    const step_keys = [_][]const u8{ "active_goal", "last_status" };
    const step_vals = [_]StateValue{
        StateValue{ .tag = .null_value, .data = .{ .none = {} } },
        StateValue{ .tag = .string, .data = .{ .str = "completed" } },
    };
    try engine.step(&step_keys, &step_vals);

    const status = engine.get("last_status");
    if (status) |st| {
        std.debug.assert(st.tag == .string);
    }
}


