 Architecture Overview

To enforce strict runtime efficiency and prevent transcript context collapse across longhorizon trajectories, the system implements the Typed Evidence Graph & Quantified Diversity Agenda Dispatcher derived from Praxist ().[1]

Instead of accumulating linear chat histories or unstructured text logs, the runtime externalizes execution state into four formal frontier lanes:
1. Confirmed
2. Candidate
3. Diagnostic
4. Validation

Validated empirical insights are converted into durable, queryable Gems that govern future generation cycles without replaying historical trajectories.[1]

zig
const std = @import("std");

pub const FrontierLane = enum(u8) {
    confirmed = 0,
    candidate = 1,
    diagnostic = 2,
    validation = 3,
};

pub const EvidenceFinding = struct {
    finding_id: u64,
    parent_finding_id: ?u64,
    lane: FrontierLane,
    evidence_score: f32,
    claim_length: usize,
    claim_data: [256]u8,
    is_durable_gem: bool,
};

pub const DiversitySlot = struct {
    allocated_budget: u32,
    consumed_budget: u32,
    active_findings: u32,
    lane_mask: u8,
};

pub const LineageGraphEngine = struct {
    allocator: std.mem.Allocator,
    findings_pool: std.ArrayList(EvidenceFinding),
    diversity_lanes: [4]DiversitySlot,
    gem_count: u32,

    pub fn init(allocator: std.mem.Allocator, lane_budgets: [4]u32) LineageGraphEngine {
        var slots: [4]DiversitySlot = undefined;
        for (0..4) |i| {
            slots[i] = .{
                .allocated_budget = lane_budgets[i],
                .consumed_budget = 0,
                .active_findings = 0,
                .lane_mask = @as(u8, 1) << @as(u3, @intCast(i)),
            };
        }
        return .{
            .allocator = allocator,
            .findings_pool = std.ArrayList(EvidenceFinding).init(allocator),
            .diversity_lanes = slots,
            .gem_count = 0,
        };
    }

    pub fn deinit(self: *LineageGraphEngine) void {
        self.findings_pool.deinit();
    }

    pub fn registerFinding(
        self: *LineageGraphEngine,
        parent_id: ?u64,
        lane: FrontierLane,
        score: f32,
        claim: []const u8,
        promote_to_gem: bool,
    ) !u64 {
        const lane_idx = @intFromEnum(lane);
        const next_id: u64 = @as(u64, self.findings_pool.items.len) + 1;

        var finding = EvidenceFinding{
            .finding_id = next_id,
            .parent_finding_id = parent_id,
            .lane = lane,
            .evidence_score = score,
            .claim_length = @min(claim.len, 256),
            .claim_data = undefined,
            .is_durable_gem = promote_to_gem,
        };

        @memset(&finding.claim_data, 0);
        @memcpy(finding.claim_data[0..finding.claim_length], claim[0..finding.claim_length]);

        try self.findings_pool.append(finding);

        self.diversity_lanes[lane_idx].active_findings += 1;
        self.diversity_lanes[lane_idx].consumed_budget += 1;

        if (promote_to_gem) {
            self.gem_count += 1;
        }

        return next_id;
    }

    pub fn selectNextAgenda(self: *const LineageGraphEngine) ?FrontierLane {
        var best_lane: ?FrontierLane = null;
        var max_remaining_capacity: i64 = -1;

        for (0..4) |i| {
            const lane_slot = self.diversity_lanes[i];
            const remaining: i64 = @as(i64, lane_slot.allocated_budget) - @as(i64, lane_slot.consumed_budget);
            if (remaining > max_remaining_capacity and remaining > 0) {
                max_remaining_capacity = remaining;
                best_lane = @as(FrontierLane, @enumFromInt(@as(u8, @intCast(i))));
            }
        }

        return best_lane;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const budgets = [4]u32{ 100, 200, 50, 80 };
    var engine = LineageGraphEngine.init(allocator, budgets);
    defer engine.deinit();

    const root_claim = "Base coordinate configuration established";
    const root_id = try engine.registerFinding(null, .confirmed, 1.0, root_claim, true);

    const cand_claim = "Hypothesis perturbation across non-isomorphic basin";
    const cand_id = try engine.registerFinding(root_id, .candidate, 0.88, cand_claim, false);

    _ = cand_id;

    const next_target_lane = engine.selectNextAgenda();
    if (next_target_lane) |lane| {
        std.debug.assert(lane == .candidate);
    }
}


